const STY = (bg) => `position:absolute;width:800px;height:180px;left:70px;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;border-radius:46px;box-shadow:0 26px 40px -14px rgba(0,0,0,.5),inset 0 4px 0 rgba(255,255,255,.5);background:${bg};color:#ffffff;font-family:inherit;font-weight:800;line-height:1.1;font-size:52px;opacity:0;`;
const B1 = `linear-gradient(180deg,color-mix(in srgb,var(--acc) 72%,#fff),var(--acc) 55%,color-mix(in srgb,var(--acc) 84%,#000))`;
const B2 = `linear-gradient(180deg,color-mix(in srgb,var(--acc2) 72%,#fff),var(--acc2) 55%,color-mix(in srgb,var(--acc2) 84%,#000))`;
const B_STAMP = `background:#ffffff;color:#0b1020;padding:10px 30px;border-radius:20px;font-size:38px;margin-top:15px;opacity:0;`;

root.innerHTML = `
  <div id="c0" style="${STY(B1)}top:80px;">HALLMARK<br>SLOPLINT SCAN</div>
  <svg style="position:absolute;width:940px;height:1060px;fill:none;stroke:#ffffff;stroke-width:12;stroke-linecap:round;opacity:0.3">
    <path id="l0" d="M470 260 L280 480" />
    <path id="l1" d="M470 260 L660 480" />
  </svg>
  <div id="c1" style="${STY(B2)}top:480px;width:420px;left:40px;height:240px;">
    BROKEN<br>LAYOUTS
    <div id="s1" style="${B_STAMP}">BLOCKED</div>
  </div>
  <div id="c2" style="${STY(B2)}top:480px;width:420px;left:480px;height:240px;">
    EMPTY<br>FRAMES
    <div id="s2" style="${B_STAMP}">BLOCKED</div>
  </div>
  <div id="msg" style="position:absolute;top:840px;width:100%;text-align:center;color:#ffffff;font-size:48px;font-weight:900;opacity:0;">ELIMINATING AI SLOP</div>
`;

const items = [root.querySelector('#c0'), root.querySelector('#c1'), root.querySelector('#c2')];
const stamps = [root.querySelector('#s1'), root.querySelector('#s2')];
const lines = [root.querySelector('#l0'), root.querySelector('#l1')].map(el => {
  const len = el.getTotalLength();
  el.style.strokeDasharray = len;
  el.style.strokeDashoffset = len;
  return { el, len };
});
const msg = root.querySelector('#msg');

function frame(t, p, d) {
  const p_clamped = Math.min(t, d * 0.6);

  // Header Entrance
  const s0 = spr(p_clamped, 0.2, 0.85, 8);
  items[0].style.opacity = s0;
  items[0].style.transform = `translateY(${lerp(30, 0, s0)}px)`;

  // Lines drawing
  const pLine = clamp((p_clamped - 1.0) * 1.5);
  lines.forEach(l => l.el.style.strokeDashoffset = l.len * (1 - E_OUT(pLine)));

  // Bottom Cards Entrance
  const sBottom = spr(p_clamped, 1.8, 0.8, 8);
  [1, 2].forEach(i => {
    items[i].style.opacity = sBottom;
    items[i].style.transform = `translateY(${lerp(40, 0, sBottom)}px)`;
  });

  // Blocked Stamps
  const sStamp = spr(p_clamped, 2.8, 0.7, 10);
  stamps.forEach(s => {
    s.style.opacity = sStamp;
    s.style.transform = `scale(${lerp(0.6, 1, sStamp)})`;
  });

  // Final Message
  const sMsg = spr(p_clamped, 3.2, 0.9, 6);
  msg.style.opacity = sMsg;
  msg.style.transform = `translateY(${lerp(20, 0, sMsg)}px)`;

  // Visual rejection indicator
  if (sStamp > 0.1) {
    [1, 2].forEach(i => {
      items[i].style.filter = `saturate(${lerp(1, 0.2, sStamp)}) brightness(${lerp(1, 0.7, sStamp)})`;
    });
  }
}
